// Builds TLD -> RDAP base URL map from the IANA bootstrap file (dns.json)
// Mode: Run Once for All Items
// Input: raw dns.json body from 'Fetch RDAP Bootstrap'
// Structure per RFC 9224: { services: [ [ [tld, tld...], [url, url...] ], ... ] }

const resp = $json;
const map = {};
const services = resp.services || [];

for (const svc of services) {
  const tlds = svc[0] || [];
  const urls = svc[1] || [];
  // Prefer https endpoints
  const httpsUrl = urls.find(u => String(u).startsWith('https://')) || urls[0];
  if (!httpsUrl) continue;
  const base = httpsUrl.endsWith('/') ? httpsUrl : httpsUrl + '/';
  for (const tld of tlds) {
    map[String(tld).toLowerCase()] = base;
  }
}

// --- Stealth RDAP overrides ---
// These registries run working RDAP servers that are NOT listed in the IANA bootstrap
map['io'] = 'https://rdap.identitydigital.services/rdap/';
map['de'] = 'https://rdap.denic.de/'; // NOTE: DENIC withholds expiry dates by policy

return [{
  json: {
    tldMap: map,
    tldCount: Object.keys(map).length,
    fetchedAt: new Date().toISOString(),
  }
}];

// Mode: Run Once for Each Item
// Extracts hostname, root domain, and resolves the correct RDAP endpoint per TLD
// Uses regex (NOT new URL() - unreliable in n8n sandbox)

const item = $json;
const rawUrl = String(item.url || '').trim();

// Strip protocol and path
let hostname = rawUrl.replace(/^https?:\/\//i, '').replace(/\/.*$/, '').trim();
hostname = hostname.replace(/^www\./i, '');

// Extract root domain (RDAP only works on root domains, not subdomains)
const parts = hostname.split('.');
let rootDomain = hostname;
if (parts.length >= 3) {
  const secondLast = parts[parts.length - 2].toLowerCase();
  const twoPartTLDs = ['co', 'com', 'net', 'org', 'gov', 'edu', 'ac'];
  if (twoPartTLDs.includes(secondLast)) {
    rootDomain = parts.slice(-3).join('.'); // example.co.uk
  } else {
    rootDomain = parts.slice(-2).join('.'); // sub.example.com -> example.com
  }
}

// Resolve RDAP endpoint from the TLD map built earlier
const tld = rootDomain.split('.').pop().toLowerCase();
const tldMap = $('Build TLD Map').first().json.tldMap || {};
const rdapBase = tldMap[tld] || null;
const tldSupported = rdapBase !== null;
// Fallback base keeps the HTTP node from erroring on an empty URL;
// an unmapped TLD will simply 404 and be treated as 'no expiry data'
const rdapUrl = (rdapBase || 'https://rdap.identitydigital.services/rdap/') + 'domain/' + rootDomain;

// Registries that withhold expiry dates by policy
const expiryWithheld = (tld === 'de' || tld === 'ch');

// Full URL for uptime check
let fullUrl = rawUrl;
if (!fullUrl.startsWith('http://') && !fullUrl.startsWith('https://')) {
  fullUrl = 'https://' + fullUrl;
}

return {
  json: {
    ...item,
    hostname: hostname,           // full hostname for SSL check
    domainForRdap: rootDomain,    // root domain for RDAP
    tld: tld,
    rdapUrl: rdapUrl,             // resolved registry RDAP endpoint
    tldSupported: tldSupported,
    expiryWithheld: expiryWithheld,
    fullUrl: fullUrl,             // for uptime check
  }
};

// Combine three check results and compute alert tier
// Mode: Run Once for Each Item

const siteData    = $('Prepare Domain').item.json;
const domainResp  = $('Check Domain (RDAP)').item.json;
const sslResp     = $('Check SSL').item.json;
const uptimeResp  = $('Check Uptime').item.json;

const now = new Date();

// ---- Parse Domain expiry from RDAP response (RFC 9083) ----
// events[] -> eventAction 'expiration' (registry) or 'registrar expiration' (fallback)
let domainDaysLeft = null;
let domainStatus = 'unknown';
try {
  if (siteData.expiryWithheld) {
    domainStatus = 'registry_withholds_expiry'; // e.g. .de / .ch - no date published
  } else if (!siteData.tldSupported) {
    domainStatus = 'tld_not_in_bootstrap';
  }
  const events = domainResp?.events || [];
  const expiryEvent =
    events.find(e => e.eventAction === 'expiration') ||
    events.find(e => e.eventAction === 'registrar expiration');
  if (expiryEvent?.eventDate) {
    const expiry = new Date(expiryEvent.eventDate);
    domainDaysLeft = Math.floor((expiry - now) / 86400000);
    domainStatus = 'ok';
  } else if (domainStatus === 'unknown') {
    domainStatus = 'no_expiry_in_response';
  }
} catch (e) {
  domainStatus = 'parse_error';
}

// ---- Parse SSL expiry from nslookup.io response ----
// Primary field: daysUntilExpiry (live TLS handshake result)
// Fallbacks cover possible key variants since the keyless schema is not fully published
let sslDaysLeft = null;
let sslStatus = 'unknown';
try {
  const s = sslResp || {};
  const inner = s.result || s.certificate || s;
  const numCand = (inner.daysUntilExpiry ?? inner.days_until_expiry ?? inner.daysLeft ?? inner.days_left ?? null);
  if (numCand !== null && numCand !== undefined && !isNaN(Number(numCand))) {
    sslDaysLeft = Math.floor(Number(numCand));
    sslStatus = 'ok';
  } else {
    const dateStr = inner.expiry || inner.expiresAt || inner.validTo || inner.valid_till || inner.notAfter || inner.not_after || null;
    if (dateStr) {
      const expiry = new Date(dateStr);
      if (!isNaN(expiry.getTime())) {
        sslDaysLeft = Math.floor((expiry - now) / 86400000);
        sslStatus = 'ok';
      } else {
        sslStatus = 'unparseable_date';
      }
    } else {
      sslStatus = 'no_data_in_response';
    }
  }
} catch (e) {
  sslStatus = 'parse_error';
}

// ---- Parse Uptime from direct HTTP check ----
let httpStatus = 0;
try {
  httpStatus = Number(uptimeResp?.statusCode || uptimeResp?.status || 0);
} catch (e) {}

// ---- Compute individual tiers ----
function computeTier(daysLeft) {
  if (daysLeft === null || daysLeft === undefined) return 0;
  if (daysLeft < 0) return 6;   // expired
  if (daysLeft <= 1) return 5;
  if (daysLeft <= 7) return 4;
  if (daysLeft <= 14) return 3;
  if (daysLeft <= 30) return 2;
  if (daysLeft <= 60) return 1;
  return 0;
}

const domainTier = computeTier(domainDaysLeft);
const sslTier = computeTier(sslDaysLeft);
const uptimeTier = (httpStatus >= 200 && httpStatus < 400) ? 0 : 6;

const maxTier = Math.max(domainTier, sslTier, uptimeTier);

// ---- Priority-based alert threshold ----
const priority = String(siteData.priority || 'medium').toLowerCase().trim();
let minAlertTier = 3;
if (priority === 'high') minAlertTier = 2;
else if (priority === 'low') minAlertTier = 4;

const needsAlert = maxTier >= minAlertTier;

// ---- Tier metadata ----
const tierLabels = {
  0: { label: 'HEALTHY',      emoji: '\u2705' },
  1: { label: 'INFO',         emoji: '\ud83d\udcc5' },
  2: { label: 'REMINDER',     emoji: '\ud83d\udd14' },
  3: { label: 'WARNING',      emoji: '\u26a0\ufe0f' },
  4: { label: 'URGENT',       emoji: '\ud83d\udea8' },
  5: { label: 'EMERGENCY',    emoji: '\ud83c\udd98' },
  6: { label: 'DOWN/EXPIRED', emoji: '\u274c' }
};
const tierInfo = tierLabels[maxTier];

// ---- Issues list ----
const issues = [];
if (domainTier === 6) issues.push('Domain EXPIRED ' + Math.abs(domainDaysLeft || 0) + ' days ago');
else if (domainTier > 0) issues.push('Domain expires in ' + domainDaysLeft + ' days');
if (domainStatus === 'registry_withholds_expiry') issues.push('Domain expiry not published by registry (' + siteData.tld + ')');

if (sslTier === 6) issues.push('SSL EXPIRED ' + Math.abs(sslDaysLeft || 0) + ' days ago');
else if (sslTier > 0) issues.push('SSL expires in ' + sslDaysLeft + ' days');

if (uptimeTier > 0) issues.push('Site DOWN (HTTP ' + httpStatus + ')');

return {
  json: {
    url: siteData.url,
    hostname: siteData.hostname,
    client_name: siteData.client_name || '',
    project_name: siteData.project_name || '',
    priority: priority,
    domain_days_left: domainDaysLeft,
    ssl_days_left: sslDaysLeft,
    http_status: httpStatus,
    domain_status: domainStatus,
    ssl_status: sslStatus,
    alert_tier: maxTier,
    alert_label: tierInfo.label,
    alert_emoji: tierInfo.emoji,
    issues_text: issues.join('\n\u2022 '),
    needs_alert: needsAlert,
    checked_at: now.toISOString(),
    row_number: siteData.row_number || null,
  }
};

// Aggregate all site check results for weekly summary
// Mode: Run Once for All Items

const allSites = $('Analyze & Compute Tier').all().map(i => i.json);
const cfg = $('Configuration').first().json;

const healthy = allSites.filter(s => s.alert_tier === 0);
const attentionNeeded = allSites.filter(s => s.alert_tier > 0);
const critical = allSites.filter(s => s.alert_tier >= 4);

const attentionByClient = {};
for (const site of attentionNeeded) {
  const key = site.client_name || 'Unknown';
  if (!attentionByClient[key]) attentionByClient[key] = [];
  attentionByClient[key].push(site);
}

const today = new Date();
const dayOfWeek = today.getDay();
const digestDay = Number(cfg.weeklyDigestDay) || 1;
const isDigestDay = dayOfWeek === digestDay && cfg.weeklyDigestEnabled === true;

let summaryText = '';
if (isDigestDay) {
  summaryText = '\ud83d\udcca *Weekly Health Summary*\n\n';
  summaryText += 'Sites Monitored: ' + allSites.length + '\n';
  summaryText += '\u2705 Healthy: ' + healthy.length + '\n';
  summaryText += '\u26a0\ufe0f Attention Needed: ' + attentionNeeded.length + '\n';
  summaryText += '\ud83d\udea8 Critical: ' + critical.length + '\n\n';

  if (attentionNeeded.length > 0) {
    summaryText += '*Sites Needing Attention:*\n';
    for (const clientName of Object.keys(attentionByClient)) {
      summaryText += '\n_' + clientName + ':_\n';
      for (const site of attentionByClient[clientName]) {
        summaryText += '\u2022 ' + site.hostname + ' - ' + site.alert_label + '\n';
        if (site.domain_days_left !== null && site.domain_days_left <= 60) {
          summaryText += '   Domain: ' + site.domain_days_left + ' days\n';
        }
        if (site.ssl_days_left !== null && site.ssl_days_left <= 60) {
          summaryText += '   SSL: ' + site.ssl_days_left + ' days\n';
        }
      }
    }
  } else {
    summaryText += '_All sites healthy! No action needed._';
  }
}

return [{
  json: {
    total_sites: allSites.length,
    healthy_count: healthy.length,
    attention_count: attentionNeeded.length,
    critical_count: critical.length,
    is_digest_day: isDigestDay,
    digest_message: summaryText,
    checked_at: new Date().toISOString(),
  }
}];
